import React, { useState, useEffect } from 'react';
import { getUsers, deleteUser, updateUser } from '../services/api';

const UserManagement = () => {
  const [users, setUsers] = useState([]); // Store the list of users
  const [loading, setLoading] = useState(true); // Indicate loading state
  const [error, setError] = useState(null); // Handle errors
  const [editingUser, setEditingUser] = useState(null); // User being edited
  const [updatedRole, setUpdatedRole] = useState(''); // Role being updated

  // Fetch users when component mounts
  useEffect(() => {
    const fetchUsers = async () => {
      setLoading(true);
      try {
        const response = await getUsers();
        console.log("Fetched Users:", response);
        if (Array.isArray(response)) {
          setUsers(response); // Update users state
          setError(null); // Clear errors
        } else {
          throw new Error('Invalid user data format.');
        }
      } catch (error) {
        console.error('Error fetching users:', error);
        setError('Error fetching users. Please try again later.');
      } finally {
        setLoading(false);
      }
    };
    fetchUsers();
  }, []);

  // Handle delete user
  const handleDelete = async (userId) => {
    try {
      await deleteUser(userId);
      setUsers((prevUsers) => prevUsers.filter(user => user._id !== userId));
      setError(null); // Clear errors on success
    } catch (error) {
      console.error('Error deleting user:', error);
      setError('Error deleting user. Please try again later.');
    }
  };

  // Handle update user
  const handleUpdate = async (userId, updatedData) => {
    try {
      const updatedUser = await updateUser(userId, updatedData);
      console.log("Updated User:", updatedUser);
      setUsers((prevUsers) =>
        prevUsers.map((user) => (user._id === userId ? updatedUser : user))
      );
      setEditingUser(null); // Close the edit form
      setError(null); // Clear errors
    } catch (error) {
      console.error('Error updating user:', error);
      setError('Error updating user. Please try again later.');
    }
  };

  // Open edit form for a user
  const openEditForm = (user) => {
  setEditingUser({ ...user }); // Create a copy to allow edits without affecting the original user object
  setUpdatedRole(user.role);  // Set initial role
};

  // Close edit form
  const closeEditForm = () => {
    setEditingUser(null);
    setUpdatedRole('');
  };

  return (
    <div>
      <h1>User Management</h1>
      {loading && <p>Loading users...</p>}
      {error && <p style={{ color: 'red' }}>{error}</p>}

      {users.length > 0 ? (
        <table>
          <thead>
            <tr>
              <th>Username</th>
              <th>Role</th>
              <th>Franchise</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => (
              <tr key={user._id}>
                <td>{user.username}</td>
                <td>{user.role}</td>
                <td>{user.franchise?.name || 'N/A'}</td>
                <td>
                  <button onClick={() => openEditForm(user)}>Edit</button>
                  <button onClick={() => handleDelete(user._id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No users found.</p>
      )}

      {editingUser && (
        <div className="edit-form">
          <h2>Edit User</h2>
          <form
            onSubmit={(e) => {
              e.preventDefault();
              handleUpdate(editingUser._id, { role: updatedRole });
            }}
          >
            <div>
              <label htmlFor="username">Username:</label>
              <input id="username" type="text" value={editingUser.username}  />
            </div>
            <div>
              <label htmlFor="role">Role:</label>
              <select
                id="role"
                value={updatedRole}
                onChange={(e) => setUpdatedRole(e.target.value)}
              >
                <option value="user">User</option>
                <option value="admin">Admin</option>
              </select>
            </div>
            <div>
              <button type="submit">Save Changes</button>
              <button type="button" onClick={closeEditForm}>Cancel</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default UserManagement;
